def solve(data):
    stack, quote, escaped = [], '', False
    matching = {')': '(', ']': '[', '}': '{'}
    for ch in data:
        if quote:
            if escaped:
                escaped = False
            elif ch == '\\':
                escaped = True
            elif ch == quote:
                quote = ''
        elif ch in ['"', "'"]:
            quote = ch
        elif ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack.pop() != matching[ch]:
                return False
    return not stack and not quote

