def solve(data):
    best = 0
    for mask in range(1 << len(data)):
        chosen = sorted(data[i] for i in range(len(data)) if mask >> i & 1)
        if all(chosen[i-1][1] <= chosen[i][0] for i in range(1, len(chosen))):
            best = max(best, sum(x[2] for x in chosen))
    return best

